import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
import hashlib
import hmac

app = Flask(__name__)

SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')
ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp', 'pdf']
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def verify_signature(payload, signature):
    """Verify HMAC signature for API authentication"""
    expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    """Convert documents between formats using LibreOffice headless mode"""
    if 'file' not in request.files:
        return jsonify({'error': 'no file provided'}), 400

    uploaded = request.files['file']
    output_format = request.form.get('format', 'pdf')

    if output_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'unsupported format: {output_format}'}), 400

    if uploaded.content_length and uploaded.content_length > MAX_FILE_SIZE:
        return jsonify({'error': 'file too large'}), 413

    with tempfile.TemporaryDirectory() as tmpdir:
        input_path = os.path.join(tmpdir, uploaded.filename)
        uploaded.save(input_path)

        # Convert using LibreOffice
        cmd = f'libreoffice --headless --convert-to {output_format} --outdir {tmpdir} "{input_path}"'
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)

        if result.returncode != 0:
            return jsonify({'error': 'conversion failed', 'detail': result.stderr.decode()[:200]}), 500

        base_name = os.path.splitext(uploaded.filename)[0]
        output_path = os.path.join(tmpdir, f'{base_name}.{output_format}')

        if not os.path.exists(output_path):
            return jsonify({'error': 'output file not generated'}), 500

        return send_file(output_path, as_attachment=True)

@app.route('/api/v1/thumbnail', methods=['POST'])
def generate_thumbnail():
    """Generate thumbnail from uploaded image using ImageMagick"""
    if 'file' not in request.files:
        return jsonify({'error': 'no file provided'}), 400

    uploaded = request.files['file']
    width = request.form.get('width', '200')
    height = request.form.get('height', '200')

    # Validate dimensions are numeric
    if not width.isdigit() or not height.isdigit():
        return jsonify({'error': 'dimensions must be numeric'}), 400

    with tempfile.TemporaryDirectory() as tmpdir:
        input_path = os.path.join(tmpdir, uploaded.filename)
        uploaded.save(input_path)
        output_path = os.path.join(tmpdir, 'thumb.png')

        cmd = f'convert "{input_path}" -resize {width}x{height} "{output_path}"'
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=15)

        if result.returncode != 0:
            return jsonify({'error': 'thumbnail generation failed'}), 500

        return send_file(output_path, as_attachment=True)

@app.route('/api/v1/metadata', methods=['POST'])
def extract_metadata():
    """Extract metadata from uploaded file using exiftool"""
    if 'file' not in request.files:
        return jsonify({'error': 'no file provided'}), 400

    uploaded = request.files['file']

    with tempfile.TemporaryDirectory() as tmpdir:
        input_path = os.path.join(tmpdir, uploaded.filename)
        uploaded.save(input_path)

        cmd = ['exiftool', '-json', input_path]
        result = subprocess.run(cmd, capture_output=True, timeout=10)

        if result.returncode != 0:
            return jsonify({'error': 'metadata extraction failed'}), 500

        import json
        metadata = json.loads(result.stdout)
        return jsonify({'metadata': metadata[0] if metadata else {}})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
